mapper.sql:
owner_key = #{ownerKey} and kind = #{kind}
and (

    content_hash = #{contentHash} or



        target_id = #{targetId}


        album_id = #{albumId} and seq = #{seq}


)

mapper.insert:
insert into media_favorite (owner_key, kind, target_id, album_id, seq, content_hash, created_at)
select #{toOwnerKey}, f.kind, f.target_id, f.album_id, f.seq, f.content_hash, f.created_at
  from media_favorite f
 where f.owner_key = #{fromOwnerKey}
   and not exists (
       select 1 from media_favorite x
        where x.owner_key = #{toOwnerKey}
          and x.kind = f.kind
          and (
              (f.content_hash is not null and x.content_hash = f.content_hash)
           or (f.content_hash is null and (
                  (f.kind = 'video' and x.target_id = f.target_id)
               or (f.kind = 'photo' and x.album_id = f.album_id and x.seq = f.seq)
              ))
          )
   )
